package fitfile

import (
	"archive/zip"
	"bytes"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

// maxNestedZipSize bounds an inner archive that has to be buffered in memory.
// The Garmin bulk export nests the FIT files in UploadedFiles_*.zip parts.
const maxNestedZipSize = 1 << 30

// maxZipDepth allows export.zip → UploadedFiles_*.zip → *.fit and no deeper.
const maxZipDepth = 2

// Source identifies where a FIT file was found, e.g.
// "export.zip!DI_CONNECT/…/UploadedFiles_0-_Part1.zip!123_456.fit".
type Source struct {
	Path string
	// FileNumber is the long number at the end of the file name, if any. In the
	// Garmin bulk export (<e-mail>_<number>.fit) it identifies the uploaded
	// file, NOT the Garmin Connect activity ID (verified 23.10.2026, spike S2).
	FileNumber string
}

// VisitFunc receives every FIT file. Returning an error aborts the walk.
type VisitFunc func(src Source, r io.Reader) error

var fileNumberPattern = regexp.MustCompile(`(\d{6,})(?:_activity)?\.fit$`)

func newSource(path string) Source {
	src := Source{Path: path}
	if m := fileNumberPattern.FindStringSubmatch(strings.ToLower(path)); m != nil {
		src.FileNumber = m[1]
	}
	return src
}

func isFIT(name string) bool { return strings.EqualFold(filepath.Ext(name), ".fit") }
func isZip(name string) bool { return strings.EqualFold(filepath.Ext(name), ".zip") }

// Walk visits all FIT files below root. root may be a FIT file, a ZIP archive
// or a directory; ZIP archives are searched including one nested level.
func Walk(root string, visit VisitFunc) error {
	return filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		switch {
		case d.IsDir():
			return nil
		case isFIT(path):
			f, err := os.Open(path)
			if err != nil {
				return err
			}
			defer f.Close()
			return visit(newSource(path), f)
		case isZip(path):
			zr, err := zip.OpenReader(path)
			if err != nil {
				return fmt.Errorf("open %s: %w", path, err)
			}
			defer zr.Close()
			return walkZip(&zr.Reader, path, 1, visit)
		}
		return nil
	})
}

func walkZip(zr *zip.Reader, prefix string, depth int, visit VisitFunc) error {
	for _, zf := range zr.File {
		if zf.FileInfo().IsDir() {
			continue
		}
		name := prefix + "!" + zf.Name
		switch {
		case isFIT(zf.Name):
			if err := visitZipEntry(zf, name, visit); err != nil {
				return err
			}
		case isZip(zf.Name) && depth < maxZipDepth:
			inner, err := readZipEntry(zf, maxNestedZipSize)
			if err != nil {
				return fmt.Errorf("%s: %w", name, err)
			}
			izr, err := zip.NewReader(bytes.NewReader(inner), int64(len(inner)))
			if err != nil {
				return fmt.Errorf("%s: %w", name, err)
			}
			if err := walkZip(izr, name, depth+1, visit); err != nil {
				return err
			}
		}
	}
	return nil
}

func visitZipEntry(zf *zip.File, name string, visit VisitFunc) error {
	rc, err := zf.Open()
	if err != nil {
		return fmt.Errorf("%s: %w", name, err)
	}
	defer rc.Close()
	return visit(newSource(name), rc)
}

var errTooLarge = errors.New("archive entry too large")

func readZipEntry(zf *zip.File, limit int64) ([]byte, error) {
	rc, err := zf.Open()
	if err != nil {
		return nil, err
	}
	defer rc.Close()
	data, err := io.ReadAll(io.LimitReader(rc, limit+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > limit {
		return nil, errTooLarge
	}
	return data, nil
}
